(function(){
  var box=$('#dos'), body=$('#dosBody'), codeEl=$('#dosCode'), open=false, lastFocus=null;
  var esc2=function(s){return esc(String(s))};

  window.openDossier=function(name){
    var d=DOSSIER[name]; if(!d)return;
    lastFocus=document.activeElement;
    codeEl.textContent=d.code;

    var h='';
    h+='<div class="dosmeta"><span>'+esc2(d.squad)+'</span><span>'+esc2(d.zone)+'</span><span>'+esc2(d.theme)+'</span>'+
       (d.ngo?'<span>NGO · '+esc2(d.ngo)+'</span>':'')+'</div>';
    h+='<h2 class="dosh">'+esc2(name)+'</h2>';
    h+='<p class="doslede">'+esc2(d.lede)+'</p>';
    h+='<p class="dosnote">'+esc2(d.when)+' &middot; '+esc2(d.where)+'</p>';
    h+='<p class="dosnote">Signed off on site by '+esc2(d.auth)+'</p>';

    if(d.pics>0){
      var strip='';
      for(var i=1;i<=d.pics;i++){
        var f='assets/'+d.picpre+(i<10?'0':'')+i+'.webp';
        strip+='<img loading="lazy" decoding="async" src="'+esc2(f)+'" alt="'+esc2(name+' — project day photograph '+i)+'">';
      }
      h+='<div class="dosstrip">'+strip+'</div>';
    }
    if(d.badge)h+='<div class="dosbadge"><img loading="lazy" src="'+esc2(d.badge)+'" alt="'+esc2(name+' squad emblem')+'"></div>';
    if(d.picnote)h+='<p class="dosnote">'+esc2(d.picnote)+'</p>';

    h+='<div class="dosstats">'+d.stats.map(function(s){
      return '<div class="dosstat"><b>'+esc2(s[0])+'</b><small>'+esc2(s[1])+'</small></div>'}).join('')+'</div>';

    h+='<div class="dossec"><h4>What it set out to do, and what happened</h4>'+
      d.aims.map(function(a){
        return '<div class="dosrow"><h5>'+esc2(a[0])+'</h5><p>'+esc2(a[1])+'</p></div>'}).join('')+'</div>';

    h+='<div class="dossec"><h4>The activities</h4>'+
      d.acts.map(function(a){
        var hi=a[1]==='High'?' hi':'';
        return '<div class="dosrow"><span class="tag'+hi+'">'+esc2(a[1]==='High'?'HIGH IMPACT':'MODERATE')+'</span>'+
               '<h5>'+esc2(a[0])+'</h5><p>'+esc2(a[2])+'</p></div>'}).join('')+'</div>';

    h+='<div class="dossec"><h4>What went wrong, and what they would change</h4>'+
      d.chal.map(function(c){
        return '<div class="dosrow"><h5>'+esc2(c[0])+'</h5><p>'+esc2(c[1])+'</p>'+
               '<p><span class="lbl">NEXT TIME</span>'+esc2(c[2])+'</p></div>'}).join('')+'</div>';

    h+='<div class="dossec"><h4>The money</h4><div class="dosfin">'+
      d.fin.map(function(f){
        return '<div'+(f[2]?' class="tot"':'')+'><span>'+esc2(f[0])+'</span><b>'+esc2(f[1])+'</b></div>'}).join('')+
      '</div><p class="dosnote" style="margin-top:10px">Summary figures only. Receipts and the full financial report stay in the squad\u2019s own records.</p></div>';

    h+='<div class="dossec"><h4>Who ran it</h4><div class="dosteam">'+
      d.team.map(function(t){return '<span>'+esc2(t)+'</span>'}).join('')+
      '</div><p class="dosnote" style="margin-top:12px">Named by role. Volunteer and committee personal details are not published.</p></div>';

    if(d.close)h+='<div class="dosguard"><b>In their own words.</b> '+esc2(d.close)+'</div>';

    h+='<div class="dosguard"><b>Property notice.</b> This dossier, its photographs, the GengVolunteers and Geng Scholars marks and every squad emblem are the property of Persatuan Belia Cendekia Holistik. Reuse without written consent is prohibited. <span class="warn">PELAKU AKAN DIHUKUM.</span></div>';

    body.innerHTML=h;
    box.classList.add('on'); open=true;
    document.body.style.overflow='hidden';
    $('#dosClose').focus();
    if(typeof award==='function')award('dossier','FILE READER',20);
  };

  var shut=function(){
    if(!open)return;
    box.classList.remove('on'); open=false;
    document.body.style.overflow='';
    body.innerHTML='';
    if(lastFocus&&lastFocus.focus)lastFocus.focus();
  };
  $('#dosClose').addEventListener('click',shut);
  box.querySelector('.veil').addEventListener('click',shut);
  document.addEventListener('keydown',function(e){if(e.key==='Escape')shut()});
})();

