    x.fillStyle='#fff';x.fillText(cd,84,1044);

    var n=0;for(var i=0;i<cd.length;i++)n=(n*31+cd.charCodeAt(i))>>>0;
    x.fillStyle='rgba(255,255,255,.85)';
