/* ═══ THE 100 DAYS ═══ */
var t0=new Date(CFG.startsAt).getTime(), t1=new Date(CFG.endsAt).getTime();
var TOTAL=Math.round((t1-t0)/86400000)+1;
function human(ms){
  var s=Math.max(0,Math.floor(ms/1000)), d=Math.floor(s/86400),
      h=Math.floor(s%86400/3600), m=Math.floor(s%3600/60), x=s%60;
  return d>0? d+'D '+h+'H '+m+'M' : h+'H '+m+'M '+x+'S';
}
function tick(){
  var n=Date.now(), strip=$('#strip');
  if(n<t0){
    var dleft=Math.ceil((t0-n)/86400000);
    $('#dayLabel').textContent='COUNTDOWN TO DAY 1';
    $('#dayNum').textContent=dleft;
    $('#daySub').textContent='DAYS UNTIL 24 AUGUST · REGISTER ANY TIME';
    $('#dayPct').textContent='NOT STARTED';
    $('#dayBar').style.width='0%';
    strip.textContent='THE 100 DAYS BEGIN IN '+human(t0-n)+' · '+(WAIT?'WAITING LIST OPEN':'REGISTRATION OPEN NOW');
  }else if(n<=t1){
    var day=Math.floor((n-t0)/86400000)+1, pct=Math.round(day/TOTAL*100);
    $('#dayLabel').textContent='THE 100 DAYS';
    $('#dayNum').textContent='DAY '+day;
    $('#daySub').textContent='OF '+TOTAL+' · REGISTRATION CLOSES WHEN FULL';
    $('#dayPct').textContent=pct+'%';
    $('#dayBar').style.width=pct+'%';
    strip.textContent='DAY '+day+' OF '+TOTAL+' · '+(WAIT?'PLACES FULL, WAITING LIST OPEN':'PLACES STILL OPEN');
  }else{
    $('#dayLabel').textContent='THE 100 DAYS';
    $('#dayNum').textContent='COMPLETE';
    $('#daySub').textContent='CYCLE TWO PROGRAMME WINDOW';
    $('#dayPct').textContent='100%';
    $('#dayBar').style.width='100%';
    strip.textContent='THE 100 DAYS ARE COMPLETE · THANK YOU';
  }
}
tick(); setInterval(tick,1000);

/* ═══ LIVE VISITOR COUNT (real or hidden, never invented) ═══
   Counts up from zero on arrival, then re-checks every 30 seconds and
   nudges when the number moves. Shows nothing at all until a real
   backend answers, so no number on this page is ever made up. */
(function(){
  if(CFG.visitorCounter!=='auto')return;
  var pill=$('#visPill'), bar=$('#visBar'), box=$('#visBox'), num=$('#visNum');
  var cur=0, started=false;

  function roll(to){
    if(typeof to!=='number'||isNaN(to)||to<0)return;
    pill.hidden=false; pill.classList.add('show');
    box.style.display='block';
    if(!started){
      started=true;
      if(reduced){cur=to;bar.textContent=paint(to);num.textContent=paint(to);return}
      var from=0, t0=performance.now(), dur=1400;
      (function step(t){
        var k=Math.min(1,(t-t0)/dur), e=1-Math.pow(1-k,3);
        var v=Math.round(from+(to-from)*e);
        bar.textContent=paint(v); num.textContent=paint(v);
        if(k<1)requestAnimationFrame(step); else cur=to;
      })(t0);
      return;
    }
    if(to===cur)return;
    cur=to; bar.textContent=paint(to); num.textContent=paint(to);
    pill.classList.remove('bump'); void pill.offsetWidth; pill.classList.add('bump');
  }
  function paint(n){return n.toLocaleString('en-MY')}

  /* preview inside Claude uses the artifact store, the live site uses Apps Script */
  if(window.storage){
      var _td=$('#visToday'); if(_td)_td.textContent='LIVE';
      window.storage.get('gv-visits',true).then(function(r){
      var n=(r&&+r.value||0)+1;
      return window.storage.set('gv-visits',String(n),true).then(function(){roll(n)});
    }).catch(function(){
      window.storage.set('gv-visits','1',true).then(function(){roll(1)}).catch(function(){});
    });
    return;
  }

  if(!CFG.appsScriptUrl||CFG.appsScriptUrl.indexOf('PASTE_')===0){
    console.info('[GV] Visitor count is off until CFG.appsScriptUrl points at your deployed Apps Script.');
    return;
  }
  var ping=function(hit){
    fetch(CFG.appsScriptUrl+(hit?'?hit=1':''))
      .then(function(r){return r.json()})
      .then(function(d){ if(!d)return; roll(d.visits);
        var td=$('#visToday'); if(td&&typeof d.today==='number')td.textContent=d.today.toLocaleString('en-MY');
        var moved=false;
        if(typeof d.capacity==='number'&&d.capacity>0&&d.capacity!==CFG.capacity){CFG.capacity=d.capacity;moved=true}
        if(typeof d.filled==='number'&&d.filled!==CFG.filled){CFG.filled=d.filled;moved=true}
        if(typeof d.waitlist==='number'&&d.waitlist!==CFG.waitlist){CFG.waitlist=d.waitlist;moved=true}
        if(moved&&typeof paintPlaces==='function')paintPlaces(false);
        var ann=$('#announce');
        if(ann){ if(d.announce){ann.textContent=d.announce;ann.style.display='block'} else ann.style.display='none' } })
      .catch(function(){});
  };
  ping(true);
  setInterval(function(){ if(!document.hidden)ping(false) },30000);
  document.addEventListener('visibilitychange',function(){ if(!document.hidden)ping(false) });
})();

/* ═══ COUNTERS AND BARS ═══ */
(function(){
  var run=function(el){
    var to=+el.dataset.to, pre=el.dataset.pre||'', suf=el.dataset.suf||'';
    if(reduced){el.textContent=pre+to.toLocaleString('en-MY')+suf;return}
    var s=performance.now();
    var step=function(t){
      var p=Math.min(1,(t-s)/1400), e=1-Math.pow(1-p,3);
      el.textContent=pre+Math.round(to*e).toLocaleString('en-MY')+(p===1?suf:'');
      if(p<1)requestAnimationFrame(step)};
    requestAnimationFrame(step)};
  var o=new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(!e.isIntersecting)return;
      if(e.target.id==='recg'){
        Array.prototype.forEach.call(e.target.querySelectorAll('.n'),run);
        award('record','YOU READ THE RECEIPTS',15);
      }
      if(e.target.id==='dm'){
        Array.prototype.forEach.call(e.target.querySelectorAll('.dmb i'),function(b,i){
          setTimeout(function(){b.style.width=Math.min(100,+b.dataset.w)+'%'},i*80)});
        award('demand','YOU LISTENED TO 500 VOICES',15);
      }
      o.unobserve(e.target);
    })},{threshold:.25});
  ['#recg','#dm'].forEach(function(sel){
    var el = document.querySelector(sel);
    if(el) o.observe(el);
  });
})();

